def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(str(i))
    return result

def parsear_duracion(s):
    import re
    total_minutes = 0
    hours = re.search(r'(\d+)h', s)
    if hours:
        total_minutes += int(hours.group(1)) * 60
    minutes = re.search(r'(\d+)m', s)
    if minutes:
        total_minutes += int(minutes.group(1))
    return total_minutes

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplana(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    izquierda = 0
    derecha = len(lista) - 1
    while izquierda <= derecha:
        medio = (izquierda + derecha) // 2
        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            izquierda = medio + 1
        else:
            derecha = medio - 1
    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor = item.get(clave)
        if valor not in resultado:
            resultado[valor] = []
        resultado[valor].append(item)
    return resultado

import re

def contar_palabras(texto):
    # Convertir a minúsculas y extraer palabras usando regex
    palabras = re.findall(r'\b\w+\b', texto.lower())

    # Contar frecuencias
    conteo = {}
    for palabra in palabras:
        conteo[palabra] = conteo.get(palabra, 0) + 1

    return conteo

def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    return lista[-n:] + lista[:-n]

def a_romano(n):
    valores = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    símbolos = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
    resultado = ""
    for i in range(len(valores)):
        while n >= valores[i]:
            resultado += símbolos[i]
            n -= valores[i]
    return resultado

def desde_romano(s):
    roman_values = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }
    total = 0
    prev_value = 0
    for char in reversed(s):
        current_value = roman_values[char]
        if current_value < prev_value:
            total -= current_value
        else:
            total += current_value
        prev_value = current_value
    return total

def mayor_racha(lista):
    if not lista:
        return None

    max_element = lista[0]
    max_length = 1
    current_element = lista[0]
    current_length = 1

    for i in range(1, len(lista)):
        if lista[i] == current_element:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
                max_element = current_element
            current_element = lista[i]
            current_length = 1

    if current_length > max_length:
        max_length = current_length
        max_element = current_element

    return (max_element, max_length)

def a_snake(s):
    result = []
    for i, char in enumerate(s):
        if char.isupper():
            if i > 0:
                result.append('_')
            result.append(char.lower())
        else:
            result.append(char)
    return ''.join(result)

def primos(n):
    if n < 2:
        return []
    primos_list = []
    for i in range(2, n + 1):
        is_prime = True
        for j in range(2, int(i ** 0.5) + 1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            primos_list.append(i)
    return primos_list

def mcd(a, b):
    if a == 0:
        return b
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def es_anagrama(a, b):
    a = a.replace(" ", "").lower()
    b = b.replace(" ", "").lower()
    return sorted(a) == sorted(b)

def comprimir(s):
    if not s:
        return s

    compressed = []
    i = 0
    n = len(s)

    while i < n:
        count = 1
        while i + 1 < n and s[i + 1] == s[i]:
            count += 1
            i += 1
        compressed.append(s[i])
        compressed.append(str(count))
        i += 1

    compressed_str = ''.join(compressed)

    if len(compressed_str) < len(s):
        return compressed_str
    else:
        return s

def balanceado(texto):
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}
    for char in texto:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False
    return not stack

def transpuesta(m):
    if not m:
        return []
    return [list(row) for row in zip(*m)]

def raiz_digital(n):
    while n >= 10:
        n = sum(int(d) for d in str(n))
    return n

def n_esimo_mayor(lista, n):
    valores_distintos = sorted(list(set(lista)), reverse=True)
    if n > len(valores_distintos):
        return None
    return valores_distintos[n - 1]

def formatear_bytes(n):
    unidades = ['B', 'KB', 'MB', 'GB']
    i = 0
    while n >= 1024 and i < len(unidades) - 1:
        n /= 1024
        i += 1
    if i == 0:
        return f"{int(n)} B"
    else:
        return f"{n:.1f} {unidades[i]}"

def en_lotes(lista, tamano):
    if not lista:
        return []
    return [lista[i:i+tamano] for i in range(0, len(lista), tamano)]
